137:         /// <summary>
138:         /// 水平蛇形排序
139:         /// </summary>
140:         /// <param name="rowC">rowC</param>
141:         /// <param name="colC">colC</param>
142:         /// <param name="rowI">rowI</param>
143:         /// <param name="colI">colI</param>
144:         /// <returns>int</returns>
145:         public int SortToSnakeHorizontal(int rowC, int colC, int rowI, int colI)
146:         {
147:             if (rowI % 2 == 0)
148:             {
149:                 return rowI * colC + colI;
150:             }
151:             else
152:             {
153:                 return rowI * colC + colC - colI - 1;
154:             }
155:         }
