162:         private List<AcupointEntity> ConvertList(AcupointEntity[,] waffleSlots)
163:         {
164:             List <AcupointEntity> temp = new List<AcupointEntity>();
165:             foreach (var item in waffleSlots)
166:             {
167:                 temp.Add(item);
168:             }
169: 
170:             return temp;
171:         }

